`,e.jsxs(n.p,{children:[e.jsx(n.strong,{children:"Documented boundary."})," The ",e.jsx(n.a,{href:"https://www.fmod.com/docs/2.04/api/studio-api-eventinstance.html#fmod_studio_event_callback_type",children:"EventInstance reference"})," defines callback types separately from playback-state enums: ",e.jsx(n.code,{children:"FMOD_STUDIO_EVENT_CALLBACK_STARTING"})," reports a start request on a previously nonplaying event; ",e.jsx(n.code,{children:"STARTED"})," can be delayed by sample loading. ",e.jsx(n.code,{children:"START_FAILED"})," reports polyphony refusal, in which case STARTING, STARTED and STOPPED callbacks are not issued. Separately, ",e.jsx(n.code,{children:"getPlaybackState"})," writes the playback enum ",e.jsx(n.code,{children:"FMOD_STUDIO_PLAYBACK_STOPPED"})," for an invalid instance. This output enum is separate from the ",e.jsx(n.code,{children:"FMOD_RESULT"}),"/",e.jsx(n.code,{children:"RESULT"})," return of the C/C++/C# call; retain both. Calling ",e.jsx(n.code,{children:"start"})," on an already-playing instance restarts it."]}),`
